params.command:
$ErrorActionPreference='Stop'
if (Get-Variable PSNativeCommandUseErrorActionPreference -ErrorAction SilentlyContinue) { $PSNativeCommandUseErrorActionPreference = $false }
$src='C:\Users\Xxkan\HeavenBridgeRepo'
$work='C:\Users\Xxkan\branch-zero-reconcile'
$origin=(& git -C $src remote get-url origin | Select-Object -First 1).Trim()
if (-not $origin) { throw 'Could not resolve authenticated origin URL from HeavenBridgeRepo' }
if (-not (Test-Path (Join-Path $work '.git'))) {
  & git clone $origin $work 2>&1 | Out-Null
  if ($LASTEXITCODE -ne 0) { throw "git clone failed: $LASTEXITCODE" }
}
& git -C $work fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune 2>&1 | Out-Null
if ($LASTEXITCODE -ne 0) { throw "git fetch failed: $LASTEXITCODE" }
$deleted=@(); $deleteFailed=@(); $unique=@()
$branches=@(& git -C $work for-each-ref '--format=%(refname:strip=3)' refs/remotes/origin) |
  ForEach-Object { $_.Trim() } |
  Where-Object { $_ -and $_ -notin @('main','heaven-bridge','HEAD') -and $_ -notmatch '^origin($|/)' } |
  Sort-Object -Unique
foreach ($b in $branches) {
  $safe=$false; $reason=''
  & git -C $work merge-base --is-ancestor "origin/$b" origin/main *> $null
  if ($LASTEXITCODE -eq 0) {
    $safe=$true; $reason='ancestor-of-main'
  } else {
    $cherry=@(& git -C $work cherry origin/main "origin/$b" 2>$null)
    if ($LASTEXITCODE -eq 0) {
      $plus=@($cherry | Where-Object { $_ -match '^\+' })
      if ($plus.Count -eq 0) { $safe=$true; $reason='patch-equivalent-to-main' }
    }
  }
  if ($safe) {
    $out=@(& git -C $work push origin --delete -- $b 2>&1)
    if ($LASTEXITCODE -eq 0) {
      $deleted += [pscustomobject]@{branch=$b;reason=$reason}
    } else {
      $deleteFailed += [pscustomobject]@{branch=$b;reason=($out -join ' | ')}
    }
  } else {
    $unique += $b
  }
}
& git -C $work fetch origin '+refs/heads/*:refs/remotes/origin/*' --prune 2>&1 | Out-Null
$remaining=@(& git -C $work for-each-ref '--format=%(refname:strip=3)' refs/remotes/origin) |
  ForEach-Object { $_.Trim() } |
  Where-Object { $_ -and $_ -notin @('main','heaven-bridge','HEAD') -and $_ -notmatch '^origin($|/)' } |
  Sort-Object -Unique
[pscustomobject]@{
  mainSha=(& git -C $work rev-parse origin/main).Trim()
  deletedCount=$deleted.Count
  deleted=$deleted
  deleteFailed=$deleteFailed
  remainingCount=$remaining.Count
  remaining=$remaining
} | ConvertTo-Json -Depth 6 -Compress
